  console.error('[朗读桥] 读 panel.js 失败：' + (error && error.message))
}

// 配置（听哪些会话）和收藏（她标记的「最爱」）都存在一个小 JSON 里，重启也在
const CFG_DIR = process.env.DSH_HOME || join(homedir(), '.dsh')
const CFG_PATH = join(CFG_DIR, 'tts-bridge.json')
// 改名前的旧文件名：新文件读不到就从这儿搬，别丢了她攒的收藏
const CFG_OLD = join(CFG_DIR, 'xiao-beike-tts.json')

const DEFAULT_FOLDER = 'default'
const loadCfg = () => {
  try {
    let raw
    try {
      raw = JSON.parse(readFileSync(CFG_PATH, 'utf8'))
    } catch (e2) {
      raw = JSON.parse(readFileSync(CFG_OLD, 'utf8'))
    }
    const folders = Array.isArray(raw.folders) ? raw.folders.filter((f) => f && f.id) : []
    if (!folders.some((f) => f.id === DEFAULT_FOLDER)) folders.unshift({ id: DEFAULT_FOLDER, name: '收藏' })
    const favorites = (Array.isArray(raw.favorites) ? raw.favorites : []).map((f) =>
      Object.assign({}, f, { folder: f && f.folder ? String(f.folder) : DEFAULT_FOLDER }),
    )
    return {
      watch: Array.isArray(raw.watch) ? raw.watch.map(String) : [],
      folders: folders,
      favorites: favorites,
      everSeen: !!raw.everSeen,
    }
  } catch (error) {
    return { watch: [], folders: [{ id: DEFAULT_FOLDER, name: '收藏' }], favorites: [], everSeen: false }
  }
}
const saveCfg = (cfg) => {
  try {
    mkdirSync(CFG_DIR, { recursive: true })
    writeFileSync(CFG_PATH, JSON.stringify(cfg, null, 2), 'utf8')
  } catch (error) {
    console.error('[朗读桥] 存配置失败：' + (error && error.message))
  }
}

export function apply(ctx) {
  try {
    const state = {
      auto: true,
      queue: [],
      nextId: 1,
      recent: [],
      recentId: 1,
      history: [],
      playing: null,
      stopWanted: false, lastNext: 0, lastHello: 0,
    }
    const cfg = loadCfg()
    const say = (m) => console.log('[朗读桥] ' + m)
    // 所有接口的处理器：DSH 的门（界面用）和本机小门（扩展用）共用同一份
    const ROUTES = new Map()

    const reply = (res, code, obj) => {
      res.writeHead(code, HEADERS)
      res.end(JSON.stringify(obj))
    }
    const readJson = (req) =>
      new Promise((resolve) => {
        let raw = ''
        req.on('data', (c) => {
          raw += c
          if (raw.length > 100000) req.destroy()
        })
        req.on('end', () => {
          try {
            resolve(JSON.parse(raw || '{}'))
          } catch (error) {
            resolve({})
          }
        })
        req.on('error', () => resolve({}))
      })

    // 三道清理：播放心跳断了、被领走太久没回执、手动复位
    const sweep = () => {
      const now = Date.now()
      if (state.playing && now - state.playing.at > 120000) {
        say('播放心跳断了，当作已停')
        state.playing = null
      }
      const stale = state.queue.filter((i) => i.claimedBy && now - i.claimedAt > 150000)
      if (stale.length) {
        state.queue = state.queue.filter((i) => !(i.claimedBy && now - i.claimedAt > 150000))
        say('领走太久没回执，丢掉 ' + stale.length + ' 条')
      }
    }

    // 被她「归档」的会话：从清单里去掉，也不再听。
    // 归档只是把会话藏起来，并不会把它卸载，所以 list() 里还在 —— 得单独查这个名单。
    const archivedSet = () => {
      try {
        const ids = ctx.workspaceRegistry && ctx.workspaceRegistry.archivedSessionIds
        return new Set((ids || []).map(String))
      } catch (error) {
        return new Set()
      }
    }

    // 盯谁：完全按她勾的那份清单来。一个都没勾就不听任何会话（新用户装完自己选）
    const targets = () => {
      const arch = archivedSet()
      const out = []
      for (const id of cfg.watch) {
        if (arch.has(id)) continue
        const s = ctx.sessions.get(id)
        if (s !== undefined) out.push(s)
      }
      return out
    }

    // 会话自己的标题（DSH 会给每个会话起一个），用来显示「这是谁说的」
    const titleOf = (id) => {
      try {
        const s = ctx.sessions.get(id)
        if (s === undefined) return ''
        const snap = ctx.sessionTitle.get(s)
        return snap && snap.title ? String(snap.title) : ''
      } catch (error) {
        return ''
      }
    }

    // 按消息 id 去会话事件里把那段文字找回来（界面上的按钮用）
    // ⚠⚠⚠ 2026-10-12 修（反馈：重启电脑之后，**哪一条都念不了** ✗）
    //   病根：原来是自己去 snapshotEvents 里扒 `data.message.content` ✗
    //     DSH 一直开着时那份 content 是齐的 ✓ —— 所以哪条都能念 ✓
    //     一重启电脑，会话是从磁盘**恢复**的 →
    //       事件里那条 message 的 content 是空的 ✗（文字其实躺在 data.stream 的 text-chunks 里 ✓）
    //     → 于是"没找到这条回复的文字" ✗ → 点了什么都不做 ✓ 跟她点一万遍没关系 ✓
    //   修法：走 DSH **官方的推导路** `session.deriveMessages()` ✓
    //     （恢复过、fork 过、压缩过的会话，它都能把文字导出来 ✓）
    const 从消息里取字 = (m) => {
      const parts = []
      if (Array.isArray(m && m.content)) {
        for (const b of m.content) {
          if (b && b.type === 'text' && typeof b.text === 'string' && b.text.trim()) parts.push(b.text.trim())
        }
      }
      if (!parts.length && typeof (m && m.text) === 'string' && m.text.trim()) parts.push(m.text.trim())
      return parts.join('\n\n')
    }

    const textOfMessage = (sessionId, messageId) => {
      if (!sessionId || !messageId) return ''
      const s = ctx.sessions.get(sessionId)
      if (s === undefined) return ''
      // ① 官方推导（首选 ✓）
      try {
        if (typeof s.deriveMessages === 'function') {
          const 们 = s.deriveMessages() || []
          for (let i = 们.length - 1; i >= 0; i--) {
            const m = 们[i]
            if (!m || String(m.id) !== String(messageId)) continue
            const 文 = 从消息里取字(m)
            if (文) return 文
          }
        }
      } catch (error) {}
      // ② 退路：老办法（自己扒事件；DSH 没重启过时它是有用的 ✓）
      let events = []
      try {
        events = s.snapshotEvents(0)
      } catch (error) {
        return ''
      }
      for (let i = events.length - 1; i >= 0; i--) {
        const ev = events[i]
        if (ev.type !== 'assistant/message') continue
        const m = ev.data && ev.data.message
        if (!m || String(m.id) !== String(messageId)) continue
        const 文 = 从消息里取字(m)
        if (文) return 文
        // ③ 恢复过的会话：文字在 stream 的 text-chunks 里 ✓
        const 块 = ev.data && ev.data.stream
        if (Array.isArray(块)) {
          const 段 = []
          for (const r of 块) {
            if (r && r.type === 'text-chunks' && Array.isArray(r.texts)) {
              for (const t of r.texts) if (typeof t === 'string' && t.trim()) 段.push(t.trim())
            }
          }
          if (段.length) return 段.join('')
        }
        return ''
      }
      return ''
    }

    // ⚠⚠ 2026-09-29：桌面端那个插槽（conversation.chat.assistant-actions）
    //   **只给 messageId，不给 sessionId** —— 网页端那边两个都给，桌面端只给一个。
    //   → 只拿到 messageId 时，挨个把加载着的会话找一遍，找到哪条就算哪条。
    //     这样老界面、新界面都不用改（多花的只是几次内存里的查找）。
    const locate = (sessionId, messageId) => {
      const 试 = []
      const 加 = (id) => {
        const s = String(id || '')
        if (s && 试.indexOf(s) < 0) 试.push(s)
      }
      加(sessionId)
      try {
        for (const s of ctx.sessions.list()) 加(s.id)
      } catch (error) {}
      for (const id of 试) {
        const text = textOfMessage(id, messageId)
        if (text) return { sessionId: id, text: text }
      }
      return null
    }

    // ⚠⚠⚠ 2026-10-12 她要的：念的时候**跳掉颜文字和怪符号** ✓
    //   她爱让大肥鱼发颜文字，可朗读桥有时不念、有时念出「欧米伽」这种怪音 ✗
    //   （Ω、ω 被当字母念了 ✗；★、(๑•̀ㅂ•́)و✧ 这种也是）
    //   规则：① 括号里没有正常字的（纯颜文字）→ 整块拿掉 ✓
    //        ② emoji、箭头、图形那些 → 去掉 ✓
    //        ③ 连着两个以上「既不是汉字、也不是正常标点」的杂符号 → 去掉 ✓
    //   ⚠ 只在**进朗读队列**的时候切（面板里「最近念过」存的还是原文 ✓ 你还能看见原样）
    const 去颜文字 = (t) => {
      let s = String(t == null ? '' : t)
      s = s.replace(/[（(][^（()）]{0,30}[)）]/g, (m) =>
        /[\u4e00-\u9fa5A-Za-z0-9]/.test(m.replace(/[（()）]/g, '')) ? m : ' ',
      )
      // ② 只留「念得出来的」：汉字、字母、数字、正常标点、空白
      //    其余一律切掉 —— emoji、★♡♪、ωΩ、阿拉伯字母、西里尔字母……
      //    这些不是被跳过就是被念成怪音（「欧米伽」就是它 ✗），干脆一个都不留 ✓
      s = s.replace(/[^\u4e00-\u9fa5\u3000-\u303F\uFF00-\uFFEFA-Za-z0-9\s.,!?;:'"()\[\]…—－-]+/g, ' ')
      // ③ 纯 ASCII 的颜文字（字符白名单拦不住它们 ✗）—— 按常见样式切
      //    >_<  T_T  ><  orz  :(  ……
      //  ⚠ 中间**必须有分隔符**才算颜文字 —— 不然 `to`、`ox` 这种正常词会被吃掉 ✗
      s = s.replace(/[（(]?\s*[>＞<＜^vV][-_^.,;:·]{1,3}[>＜<^vV]\s*[)）]?/g, ' ')
      s = s.replace(/[（(]?\s*[TToO0xX][-_^.,;:·]{1,3}[TToO0xX]\s*[)）]?/g, ' ')
      s = s.replace(/\borz\b/gi, ' ')
      s = s.replace(/[:;=8][-o*']?[)(\[\]dDpP/\\|{}]/g, ' ')
      s = s.replace(/[（(]\s*[)）]/g, ' ')
      // ⚠⚠⚠ 2026-10-12 修我自己的大错 ✗：
      //   我加规则③的时候，把这下面的 `return s` **吃掉**了 ✗
      //   → 这个函数就变成"返回空" ✓ → enqueue 里 `if (!clean) return false` ✓
      //   → **一条都排不进队列** ✗ → 她点一万遍都一点动静没有 ✓
      //   （时间线也正好对上：她一重启 DSH，这段坏代码就生效了 ✗）
      s = s
        .replace(/ ([，。！？、；：）】》])/g, '$1')
        .replace(/([（【《]) /g, '$1')
        .trim()
      return s
    }

    const remember = (text) => {
      const clean = String(text == null ? '' : text).trim()
      if (!clean) return
      state.recent.unshift({ id: state.recentId++, text: clean, at: Date.now() })
      state.recent = state.recent.slice(0, 30)
    }

    const enqueue = (text, force, messageId) => {
      // ⚠⚠ 2026-10-12：这里过一道「去颜文字」（念的时候跳过 ✗→✓）
      const clean = 去颜文字(text)
      if (!clean) return false
      if (state.queue.length >= 6) state.queue.shift()
      state.queue.push({
        id: state.nextId++,
        text: clean,
        force: !!force,
        messageId: messageId ? String(messageId) : null,
        at: Date.now(),
        claimedBy: null,
        claimedAt: 0,
      })
      say('排队 ' + state.queue.length + ' 条：' + clean.slice(0, 40).replace(/\s+/g, ' '))
      return true
    }

    // 只认「一整轮说完」的助手文字；工具调用、思考框不念
    const scanTurns = createSessionTurnScanner({
      onCompleted: (text) => {
        remember(text)
        if (state.auto) enqueue(text, false, null)
      },
      onStart: (id, seq) => say('开始盯着 ' + id + '（seq=' + seq + '）'),
      onError: (error, id) => say('读 ' + id + ' 出错：' + (error && error.message)),
    })
    const scan = () => scanTurns(targets())
    ctx.effect(() => ctx.interval(scan, 1500))

    // ⭐ 设置页那个「检查更新」：查这个插件自己的仓库（地址从 package.json 读）
    const 自查更新 = createSelfUpdate({
      packageRoot: fileURLToPath(new URL('..', import.meta.url)),
      diag: (m) => say('查更新：' + m),
    })

    const route = (path, handler) => {
      // 同一份处理器挂两个面：DSH 的门（界面用）和本机小门（扩展用）。
      // ⚠ 加新接口时记得看下面「扩展接口」那张名单要不要跟着加。
      ROUTES.set(path, handler)
      return ctx.effect(() =>
        ctx.webServer.register({
          kind: 'exact',
          path: path,
          handler: async (req, res) => {
            if (req.method === 'OPTIONS') {
              res.writeHead(204, HEADERS)
              res.end()
              return
            }
            try {
              await handler(req, res)
            } catch (error) {
              say('路由 ' + path + ' 出错：' + (error && error.message))

              try {
                reply(res, 500, { ok: false, error: String(error && error.message) })
              } catch (e2) {}
            }
          },
        }),
      )
    }

    // 界面按钮：念这一条
    // ⭐ 设置页的「检查更新」：查这个插件自己的仓库（地址从 package.json 读）
    route(P + '/update', async (req, res) => {
      const u = new URL(req.url, 'http://127.0.0.1')
      const r = await 自查更新.check(u.searchParams.get('refresh') === '1')
      reply(res, 200, { ok: true, ...r })
    })

    route(P + '/speak', async (req, res) => {
      const body = await readJson(req)
      const 找 = locate(String(body.sessionId || ''), String(body.messageId || ''))
      // ⚠⚠ 2026-10-12 加的"眼睛"（她说怎么改都没用 → 不猜了，让它自己交代）：
      //   她点一下，这里就把「收到了什么 / 找到没有 / 它自己推导出几条消息、尾巴几个 id」
      //   写进一个文件 ✓ 我直接读那个文件，一眼看清卡在哪儿 ✓
      try {
        const 会话们 = ctx.sessions.list()
        const 单 = {
          at: Date.now(),
          收到: {
            sessionId: String(body.sessionId || ''),
            messageId: String(body.messageId || ''),
            她发来的字段: Object.keys(body || {}),
          },
          找到: !!找,
          会话数: 会话们.length,
          各会话: 会话们.slice(0, 8).map((s) => {
            let 数 = -1
            let 尾 = []
            try {
              const 们 = (typeof s.deriveMessages === 'function' ? s.deriveMessages() : []) || []
              数 = 们.length
              尾 = 们.slice(-3).map((m) => String((m && m.id) || ''))
            } catch (error) {
              尾 = ['取不到：' + ((error && error.message) || '')]
            }
            return { id: String(s.id), 消息数: 数, 尾巴: 尾 }
          }),
        }
        writeFileSync(join(CFG_DIR, 'tts-bridge-diag.json'), JSON.stringify(单, null, 2))
      } catch (error) {}
      if (!找) {
        reply(res, 200, { ok: false, error: '没找到这条回复的文字' })
        return
      }
      enqueue(找.text, true, body.messageId)
      const 尾 = state.queue[state.queue.length - 1]
      if (尾 && String(尾.messageId) === String(body.messageId)) 尾.sessionId = 找.sessionId
      reply(res, 200, { ok: true, waiting: state.queue.length })
    })

    // 界面按钮：停止（队列一起清掉，免得后面还排着）
    route(P + '/stop', async (req, res) => {
      state.stopWanted = true
      state.playing = null
      state.queue = []
      reply(res, 200, { ok: true })
    })

    // 界面按钮：现在有没有在出声
    route(P + '/status', (req, res) => {
      sweep()
      reply(res, 200, {
        ok: true,
        auto: state.auto,
        playing: state.playing !== null,
        waiting: state.queue.length,
      })
    })

    // 浏览器扩展：取件
    // 扩展后台来打个招呼：「我还在」（不管 DeepSeek 页面开没开）
    // 有了它，卡片就能分清「没装扩展」和「装了但页面没开」
    route(P + '/hello', (req, res) => {
      state.lastHello = Date.now()
      if (!cfg.everSeen) {
        cfg.everSeen = true
        saveCfg(cfg)
      }
      reply(res, 200, { ok: true })
    })

    route(P + '/next', async (req, res) => {
      state.lastNext = Date.now()
      if (!cfg.everSeen) {
        cfg.everSeen = true
        saveCfg(cfg)
      }
      sweep()
      const body = req.method === 'POST' ? await readJson(req) : {}
      const client = String(body.client || 'anon').slice(0, 40)
      const watching = targets().map((s) => String(s.id))
      const base = {
        ok: true,
        auto: state.auto,
        watching: watching,
        waiting: state.queue.length,
        lastError: state.history.length ? state.history[0].error : null,
      }
      if (state.stopWanted) {
        state.stopWanted = false
        base.item = { id: 0, stop: true }
        reply(res, 200, base)
        return
      }
      const head = state.queue[0]
      let item = null
      if (head && (state.auto || head.force)) {
        if (!head.claimedBy || head.claimedBy === client || Date.now() - head.claimedAt > 30000) {
          head.claimedBy = client
          head.claimedAt = Date.now()
          item = { id: head.id, text: head.text }
        }
      }
      base.item = item
      reply(res, 200, base)
    })

    route(P + '/ack', async (req, res) => {
      const body = await readJson(req)
      const id = Number(body.id)
      const item = state.queue.filter((i) => i.id === id)[0]
      state.queue = state.queue.filter((i) => i.id !== id)
      if (state.playing && state.playing.itemId === id && body.ok === false) state.playing = null
      state.history.unshift({
        id: id,
        ok: body.ok !== false,
        error: body.error ? String(body.error).slice(0, 200) : null,
        detail: body.detail ? String(body.detail).slice(0, 700) : null,
        text: item ? item.text.slice(0, 80) : null,
        at: Date.now(),
      })
      state.history = state.history.slice(0, 20)
      reply(res, 200, { ok: true })
    })

    // 扩展报告：真的在出声了 / 出完了（on:true 是心跳，on:false 无论哪条都直接清掉）
    route(P + '/playing', async (req, res) => {
      const body = await readJson(req)
      const id = Number(body.id) || 0
      if (body.on) {
        const item = state.queue.filter((i) => i.id === id)[0]
        // ⭐ 1.3.0：还在念就顺手续一下「认领时间」——
        //   长段落要念好几分钟，光靠每秒轮询续期，后台标签一被节流就可能被判「领走太久」丢掉
        if (item) item.claimedAt = Date.now()
        const msgId =
          item && item.messageId ? item.messageId : state.playing && state.playing.itemId === id ? state.playing.messageId : null
        state.playing = { itemId: id, messageId: msgId, at: Date.now() }
      } else {
        state.playing = null
      }
      reply(res, 200, { ok: true, playing: state.playing !== null })
    })

    route(P + '/auto', async (req, res) => {
      const body = await readJson(req)
      state.auto = body.auto !== false
      if (!state.auto) state.queue = []
      say('自动朗读 = ' + (state.auto ? '开' : '关'))
      reply(res, 200, { ok: true, auto: state.auto })
    })

    route(P + '/say', async (req, res) => {
      const body = await readJson(req)
      enqueue(body.text, true, null)
      reply(res, 200, { ok: true, waiting: state.queue.length })
    })

    route(P + '/reset', async (req, res) => {
      state.playing = null
      state.queue = []
      state.stopWanted = true
      reply(res, 200, { ok: true, auto: state.auto })
    })

    route(P + '/recent', (req, res) => {
      reply(res, 200, { ok: true, recent: state.recent.map((r) => ({ id: r.id, text: r.text, at: r.at })) })
    })

    route(P + '/state', (req, res) => {
      sweep()
      reply(res, 200, {
        ok: true,
        auto: state.auto,
        watching: targets().map((s) => String(s.id)),
        waiting: state.queue.length,
        playing: state.playing !== null,
        next: state.queue.length ? state.queue[0].text.slice(0, 80) : null,
        remembered: state.recent.length,
        watch: cfg.watch,
        lastNext: state.lastNext,
        lastHello: state.lastHello,
        everSeen: !!cfg.everSeen,
        extDir: EXT_DIR,
        live: ctx.sessions.list().map((s) => String(s.id)),
        favorites: cfg.favorites.length,
        // ⚠ 自己给自己留的体检口：把「首页注入」这张表读出来看一眼。
        //   桌面端卡片出不来的时候，先看这里有没有 script-src:/dsh-tts-bridge/panel.js
        injectRows: (() => {
          const 表 = []
          try {
            ctx.emit('webserver/index-inject', 表)
          } catch (error) {}
          return 表.map((r) => (r && r.kind ? r.kind + ':' + String(r.src || r.name || '') : '?'))
        })(),
        history: state.history.slice(0, 8),
      })
    })

    // ---- 配置（听哪些会话）与收藏（最爱） ----

    // 可选的会话。只列「活着的」—— 插件只能读被载入的会话，关着的它看不见。
    route(P + '/sessions', (req, res) => {
      const list = []
      const watching = cfg.watch
      const arch = archivedSet()
      const ids = new Set()
      for (const s of ctx.sessions.list()) ids.add(String(s.id))
      for (const id of watching) ids.add(id)
      // 不过滤了：之前那个 parentSession 判断会把会话筛掉，而且她想在清单里看到自己这边
      for (const id of ids) {
        if (arch.has(id)) continue
        const s = ctx.sessions.get(id)
        if (s === undefined) continue
        let title = ''
        try {
          const snap = ctx.sessionTitle.get(s)
          if (snap && snap.title) title = String(snap.title)
        } catch (error) {}
        // 还没起名字的会话（刚点开、还没说话）不列出来 —— 里面也没有东西可念。
        // 说上一句话它就有了标题，自然会出现。
        if (!title) continue
        list.push({
          id: id,
          title: title,
          watching: watching.indexOf(id) >= 0,
        })
      }
      list.sort((a, b) => String(a.title).localeCompare(String(b.title), 'zh'))
      reply(res, 200, { ok: true, sessions: list, watch: watching, live: Array.from(ids) })
    })

    // 加一个 / 去掉一个 要听的会话
    route(P + '/watch', async (req, res) => {
      const body = await readJson(req)
      const id = String(body.id || '')
      if (!id) {
        reply(res, 200, { ok: false, error: '没给会话 id' })
        return
      }
      const set = new Set(cfg.watch)
      if (body.remove) set.delete(id)
      else set.add(id)
      cfg.watch = Array.from(set)
      saveCfg(cfg)
      say('听这些会话：' + (cfg.watch.length ? cfg.watch.join(' , ') : '（一个都没选）'))
      reply(res, 200, { ok: true, watch: cfg.watch })
    })

    // 收藏 / 取消收藏某一条
    route(P + '/favorite', async (req, res) => {
      const body = await readJson(req)
      const messageId = String(body.messageId || '')
      if (!messageId) {
        reply(res, 200, { ok: false, error: '没给消息 id' })
        return
      }
      const at = cfg.favorites.findIndex((f) => String(f.messageId) === messageId)
      let on
      if (at >= 0) {
        cfg.favorites.splice(at, 1)
        on = false
      } else {
        // ⚠ 桌面端那个插槽不给 sessionId → 靠 locate 自己找出来（收藏那栏要写清是谁说的）
        const 找 = locate(String(body.sessionId || ''), messageId)
        const text = 找 ? 找.text : ''
        // 记下「这句话是谁说的」——用会话自己的标题，通用又准确
        const sid = 找 ? 找.sessionId : String(body.sessionId || '')
        const who = titleOf(sid)
        cfg.favorites.unshift({
          messageId: messageId,
          sessionId: sid,
          text: text,
          who: who,
          folder: String(body.folder || DEFAULT_FOLDER),
          at: Date.now(),
        })
        cfg.favorites = cfg.favorites.slice(0, 200)
        on = true
      }
      saveCfg(cfg)
      reply(res, 200, { ok: true, on: on, count: cfg.favorites.length })
    })

    route(P + '/favorites', (req, res) => {
      reply(res, 200, {
        ok: true,
        folders: cfg.folders.map((f) => ({
          id: String(f.id),
          name: String(f.name || f.id),
          count: cfg.favorites.filter((x) => String(x.folder) === String(f.id)).length,
        })),
        favorites: cfg.favorites.map((f) => ({
          messageId: f.messageId,
          text: String(f.text || '').slice(0, 400),
          who: String(f.who || ''),
          folder: String(f.folder || DEFAULT_FOLDER),
          at: f.at,
        })),
      })
    })

    // 建 / 改名 / 删分区。删分区只是把里面的收藏挪回默认，不删句子。
    route(P + '/folder', async (req, res) => {
      const body = await readJson(req)
      if (body.remove) {
        const id = String(body.remove)
        if (id === DEFAULT_FOLDER) {
          reply(res, 200, { ok: false, error: '默认分区不能删' })
          return
        }
        cfg.folders = cfg.folders.filter((f) => String(f.id) !== id)
        cfg.favorites = cfg.favorites.map((f) =>
          String(f.folder) === id ? Object.assign({}, f, { folder: DEFAULT_FOLDER }) : f,
        )
        saveCfg(cfg)
        reply(res, 200, { ok: true, folders: cfg.folders })
        return
      }
      const name = String(body.name || '').trim()
      if (!name) {
        reply(res, 200, { ok: false, error: '分区名不能空' })
        return
      }
      if (body.id) {
        const id = String(body.id)
        cfg.folders = cfg.folders.map((f) => (String(f.id) === id ? Object.assign({}, f, { name: name }) : f))
        saveCfg(cfg)
        reply(res, 200, { ok: true, folders: cfg.folders })
        return
      }
      const id = 'f' + Date.now().toString(36)
      cfg.folders.push({ id: id, name: name })
      saveCfg(cfg)
      reply(res, 200, { ok: true, id: id, folders: cfg.folders })
    })

    // 把一条收藏移到别的分区
    route(P + '/move', async (req, res) => {
      const body = await readJson(req)
      const messageId = String(body.messageId || '')
      const folder = String(body.folder || DEFAULT_FOLDER)
      cfg.favorites = cfg.favorites.map((f) =>
        String(f.messageId) === messageId ? Object.assign({}, f, { folder: folder }) : f,
      )
      saveCfg(cfg)
      reply(res, 200, { ok: true })
    })

    route(P + '/forget', async (req, res) => {
      const body = await readJson(req)
      const messageId = String(body.messageId || '')
      cfg.favorites = cfg.favorites.filter((f) => String(f.messageId) !== messageId)
      saveCfg(cfg)
      reply(res, 200, { ok: true, count: cfg.favorites.length })
    })

    // DSH 界面右下角那张小卡片：脚本注进每个 DSH 窗口
    // 每次现读磁盘 —— 这样改卡片只要刷新页面，不用重启 DSH
    route(P + '/panel.js', (req, res) => {
      let text = PANEL_JS
      try {
        text = readFileSync(new URL('./panel.js', import.meta.url), 'utf8')
      } catch (error) {}
      res.writeHead(200, {
        'content-type': 'application/javascript; charset=utf-8',
        'cache-control': 'no-store',
      })
      res.end(text)
    })

    // DSH 界面右下角那张小卡片：**两条路都注册一遍**。
    //  ⚠⚠ 2026-09-29（官方桌面端 DSH Desktop 报的「没有小窗口」）：
    //    桌面壳子把首页当**静态文件**直接发给窗口（dsh-app://app），
    //    **不走服务器的 renderIndex** —— 所以下面那段 tapIndex 在桌面端**一次都不会跑**，
    //    卡片就永远不出现。
    //    桌面壳子认的是**结构化注入表**：它先 collectIndexInjections()，再把每一行交给前端，
    //    前端按 kind 处理（script-src = 真去 createElement('script') 加载）✓
    //    → 老的（网页那套）走 tapIndex，新的（桌面端）走这一行；
    //      卡片文件自己有 window.__ttsBridgePanelLoaded 那道闸，两条都跑到也不会出两张。
    ctx.effect(() =>
      ctx.on('webserver/index-inject', (table) => {
        if (!Array.isArray(table)) return
        const 已有 = table.some(
          (r) => r && r.kind === 'script-src' && String(r.src || '').indexOf(P + '/panel.js') === 0,
        )
        if (!已有) table.push({ kind: 'script-src', placement: 'body', src: P + '/panel.js' })
      }),
    )

    ctx.effect(() =>
      ctx.webServer.tapIndex((html) => {
        if (html.indexOf('/dsh-tts-bridge/panel.js') >= 0) return html
        const tag = '<script src="/dsh-tts-bridge/panel.js" defer></script>'
        return html.indexOf('</body>') >= 0 ? html.replace('</body>', tag + '</body>') : html + tag
      }),
    )

    // ---------- 问路端口 + 本机小门（固定门牌） ----------
    // ⚠⚠ 2026-10-17（官方桌面端更新后）：
    //   老版桌面壳启动宿主时**写死** `--port 19387`；
    //   新版改成 `--port 0`（让系统随便挑一个空闲端口）→ 每次启动地址都不一样
    //   （19387 → 13633 → 5646 —— 已实测三次都不同）✗
    //   扩展那边"猜几个常见端口"就永远追不上 ✗
    //   → 在**固定端口**上守一个"问路员"：扩展敲这个门，它回答"我现在在哪儿" ✓
    //   这不是猜，是问。
    //
    // ⚠⚠ 2026-10-28：DSH NEXT（2.0.19-next 起）给**每一个**插件路由都套了
    //   「浏览器访问」闸 —— 没有 Electron 渲染进程的 `x-dsh-desktop-renderer`、
    //   设置里又没开「允许浏览器访问」时，一律 403 Browser access is disabled。
    //   扩展是普通浏览器客户端 → 问对了路也进不去（/state、/next 全 403）。
    //   插件自己 listen 的这个端口不归那道闸管 → 就把扩展要用的几条接口
    //   也挂到这道「本机小门」上：只认 127.0.0.1、只认 chrome-extension 来源、
    //   要带每次启动新发的令牌（令牌由 /where 发，只活在内存里）。
    const 问路端口 = [19387, 39871, 39872]
    const 本机令牌 = randomBytes(32).toString('base64url')
    // 扩展够得着的接口：只列它真的会用的。界面用的那些（/watch、/favorites、/stop…）
    // 仍然只走 DSH 的门，不上这道口。
    const 扩展接口 = [
      P + '/state',
      P + '/next',
      P + '/ack',
      P + '/playing',
      P + '/auto',
      P + '/say',
      P + '/hello',
    ]
    const 小门 = createLocalGate({
      prefix: P,
      token: 本机令牌,
      routes: ROUTES,
      allow: 扩展接口,
      dshBase: () => ctx.webServer.getOrigin() + P,
    })
    ctx.effect(() => {
      const 开着的 = []
      let 收摊 = false
      let 门牌 = 0
      const 守一个 = (端口) =>
        new Promise((resolve) => {
          const 服务器 = createServer((req, res) => {
            小门.handle(req, res, 门牌).catch(() => {
              try {
                res.writeHead(500, { 'content-type': 'application/json; charset=utf-8' })
                res.end(JSON.stringify({ ok: false, error: '出错了' }))
              } catch (error) {}
            })
          })
          服务器.once('error', () => resolve(null))
          服务器.listen(端口, '127.0.0.1', () => {
            const 地址 = 服务器.address()
            门牌 = (地址 && 地址.port) || 端口
            开着的.push(服务器)
            resolve(服务器)
          })
        })
      ;(async () => {
        for (const 端口 of 问路端口) {
          if (收摊) return
          const 成 = await 守一个(端口)
          if (成) {
            say('本机接口已就位：127.0.0.1:' + 门牌 + P)
            return
          }
        }
        say('本机端口一个都没占上（19387/39871/39872 都被占了）')
      })()
      return () => {
        收摊 = true
        for (const 服务器 of 开着的) {
          try {
            服务器.close()
          } catch (error) {}
        }
      }
    })

    say('宿主端就绪：' + P + '/next')
  } catch (error) {
    console.error('[朗读桥] 启动失败（不影响 DSH）：' + (error && error.message))
  }
}
"
    },
    {
      "path": "extension/content.js",
      "content": "// DSH 朗读桥 · 页面端（跑在 chat.deepseek.com 上）
// 流程：取到一句话 → 输进对话框发出去 → 等 DeepSeek 复述完 → 点「朗读」→ 回执。
// 判断「发出去了没有」以「有没有新的回复」为准，不看输入框清没清空（那玩意儿不准）。
// 左下角小面板：只显示一行状态（双击它可以把诊断信息回传给宿主，排错用）。

;(() => {
  const POLL_MS = 1200
  // ⚠⚠⚠ 2026-10-12 她要的（**这一版是她专用的，不往外发** ✗）：大肥鱼爱发颜文字，
  //   可朗读那边是**一字不差全念**、它自己不会判断 → 有时不念、有时念成「欧米伽」很怪 ✗
  //   → 就在最前面这句里交代清楚：表情、颜文字、特殊符号**不用重复，跳过就行** ✓
  //   （宿主那边另有一道「去颜文字」兜底 ✓ 就算它没听话，也不会被念出来 ✓）
  const PREFIX =
    '请只原样重复下面这一段，不要加任何自己的话，也不要解释。\n' +
    '里面的表情、颜文字和特殊符号（比如 (´｡• ω •｡`)、★、♡、～、Ω 这一类）不用重复，跳过就行：\n\n'
  // 注意：只能用 .ds-markdown（整条消息的容器）。
  // 以前写成 [class*="ds-markdown"]，结果把消息里每个 <p class="ds-markdown-paragraph">
  // 段落也匹配进来了 —— 段落永远排在它父亲后面，于是「末尾那条」永远是一个小段落，
  // 它就以为回复才几个字、还在长，永远等不到头。
  const MD_SEL = '.ds-markdown'
  const CLIENT = Math.random().toString(36).slice(2, 10)

  let auto = true
  let busy = false
  let dead = false
  let status = '刚启动'
  const PB = self.__ttsPlayback // playback.js（manifest 里排在本文件前面）
  if (!PB) {
    // 扩展没加载全（manifest 顺序被改过 / 只注入了一个脚本）：说清楚，别让它默默不响
    status = '扩展没加载全（缺 playback.js），卸了重装一次'
    try { paint() } catch (e) {}
    return
  }
  let curWait = null // 正在盯的那次播放（同一时刻只有一个）
  let handleGen = 0 // 第几条；旧条目迟到的收尾不许动新条目的 busy/状态
  let noteUntil = 0
  let cancelWanted = false
  let busySince = 0
  let lastWarning = null
  let curBase = null // 这次是哪个窝（3080 还是 43129）
  let curJob = null // 正在处理的那条：{ gen, base } —— 看门狗回执要写回它自己的窝

  const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

  // ---------- 小工具 ----------
  const isVisible = (el) => {
    if (!el || !el.getBoundingClientRect) return false
    const r = el.getBoundingClientRect()
    if (r.width < 2 || r.height < 2) return false
    const cs = getComputedStyle(el)
    return cs.visibility !== 'hidden' && cs.display !== 'none' && cs.opacity !== '0'
  }

  const attrs = (el) => {
    const cls = el.className && typeof el.className === 'string' ? el.className : ''
    return [
      el.getAttribute && el.getAttribute('aria-label'),
      el.getAttribute && el.getAttribute('title'),
      el.getAttribute && el.getAttribute('data-testid'),
      cls,
    ]
      .filter(Boolean)
      .join(' ')
  }

  const labels = (el) => (attrs(el) + ' ' + (el.innerText || '').trim().slice(0, 30)).toLowerCase()

  const readInput = (el) => (el.tagName === 'TEXTAREA' || el.tagName === 'INPUT' ? el.value : el.innerText || '')

  const setNativeValue = (el, value) => {
    if (el.tagName === 'TEXTAREA' || el.tagName === 'INPUT') {
      const proto = el.tagName === 'TEXTAREA' ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype
      const setter = Object.getOwnPropertyDescriptor(proto, 'value').set
      setter.call(el, value)
      el.dispatchEvent(new Event('input', { bubbles: true }))
      el.dispatchEvent(new Event('change', { bubbles: true }))
    } else {
      el.focus()
      document.execCommand('selectAll', false, null)
      document.execCommand('insertText', false, value)
      el.dispatchEvent(new Event('input', { bubbles: true }))
    }
  }

  const key = (el, type) =>
    el.dispatchEvent(
      new KeyboardEvent(type, {
        key: 'Enter',
        code: 'Enter',
        keyCode: 13,
        which: 13,
        bubbles: true,
        cancelable: true,
      }),
    )

  const dump = (root, limit) => {
    const out = []
    const all = (root || document).querySelectorAll('button, [role="button"], [aria-label], [title], [data-testid]')
    for (const el of all) {
      if (!isVisible(el)) continue
      const a = attrs(el).trim()
      if (!a) continue
      out.push(a.slice(0, 60))
      if (out.length >= (limit || 30)) break
    }
    return out
  }

  // 失败时把现场说清楚，方便照着改选择器
  function diagnostics(last) {
    const md = document.querySelectorAll(MD_SEL).length
    const near = []
    let n = last
    for (let i = 0; i < 4 && n; i++) {
      for (const el of n.querySelectorAll('button, [role="button"], [aria-label], [title]')) {
        if (near.length >= 30) break
        const a = attrs(el).trim()
        if (a) near.push((isVisible(el) ? '显' : '隐') + ':' + a.slice(0, 55))
      }
      n = n.parentElement
    }
    const kw = []
    for (const el of document.querySelectorAll('[aria-label], [title], [data-testid], [class]')) {
      const s = attrs(el)
      if (/tts|朗读|voice|speak|audio|volume/i.test(s)) {
        kw.push((isVisible(el) ? '显' : '隐') + ':' + s.slice(0, 55))
        if (kw.length >= 12) break
      }
    }
    const node = last || lastMarkdown()
    const txt = node ? (node.innerText || '').trim() : ''
    const scrolls = []
    let s = node
    for (let i = 0; i < 10 && s; i++) {
      if (s.scrollHeight && s.scrollHeight - s.clientHeight > 20) {
        const cls = s.className && typeof s.className === 'string' ? s.className.slice(0, 30) : s.tagName
        scrolls.push(cls + ' ' + Math.round(s.scrollTop) + '/' + s.scrollHeight)
      }
      s = s.parentElement
    }
    const chain = []
    let p = node
    for (let i = 0; i < 4 && p; i++) {
      const cls = p.className && typeof p.className === 'string' ? p.className.slice(0, 34) : ''
      chain.push((p.tagName || '?').toLowerCase() + '.' + cls)
      p = p.parentElement
    }
    const allBtn = []
    for (const el of document.querySelectorAll('button, [role="button"]')) {
      if (!isVisible(el)) continue
      const a = attrs(el).trim()
      if (!a) continue
      allBtn.push(a.slice(0, 40))
      if (allBtn.length >= 14) break
    }
    return (
      'markdown=' + md +
      ' 生成中=' + isGenerating() +
      ' 朗读按钮就绪=' + readReadyNearLast() +
      ' 末条字数=' + txt.length +
      ' 末条可见=' + isVisible(node) +
      ' 末条开头=' + JSON.stringify(txt.slice(0, 20)) +
      ' || 父链：' + chain.join(' > ') +
      ' || 全页按钮：' + allBtn.join(' ;; ') +
      ' || 关键词：' + kw.slice(0, 8).join(' ;; ')
    )
  }

  const fail = (msg, detail) => {
    const e = new Error(msg)
    if (detail) e.detail = detail
    return e
  }

  const short = (t, n) => {
    const s = String(t || '').replace(/\s+/g, ' ').trim()
    return s.length > n ? s.slice(0, n) + '…' : s
  }

  // ---------- 找元素 ----------
  function findInput() {
    const ta = Array.from(document.querySelectorAll('textarea')).filter(isVisible)
    if (ta.length) return ta[ta.length - 1]
    const ce = Array.from(document.querySelectorAll('[contenteditable="true"]')).filter(isVisible)
    return ce.length ? ce[ce.length - 1] : null
  }

  function findSendButton(input) {
    const all = Array.from(document.querySelectorAll('button, [role="button"]')).filter(isVisible)
    const named = all.filter((el) => /发送|send/.test(labels(el)))
    if (named.length) return named[named.length - 1]
    let box = input
    for (let i = 0; i < 7 && box; i++) {
      box = box.parentElement
      if (!box) break
      const btns = Array.from(box.querySelectorAll('button, [role="button"]')).filter(isVisible)
      if (btns.length >= 1 && btns.length <= 8) {
        btns.sort((a, b) => a.getBoundingClientRect().right - b.getBoundingClientRect().right)
        return btns[btns.length - 1]
      }
    }
    return null
  }

  const textLabel = (el) =>
    [
      el.getAttribute && el.getAttribute('aria-label'),
      el.getAttribute && el.getAttribute('title'),
      (el.innerText || '').trim().slice(0, 30),
    ]
      .filter(Boolean)
      .join(' ')

  function isGenerating() {
    const all = Array.from(document.querySelectorAll('button, [role="button"]')).filter(isVisible)
    return all.some((el) => /停止|stop/i.test(textLabel(el)) && !/朗读|播放/.test(textLabel(el)))
  }

  function lastMarkdown() {
    const md = Array.from(document.querySelectorAll(MD_SEL))
    return md.length ? md[md.length - 1] : null
  }

  function revealToolbar(node) {
    let n = node
    for (let i = 0; i < 5 && n; i++) {
      for (const t of ['pointerover', 'mouseover', 'mouseenter', 'mousemove']) {
        n.dispatchEvent(new MouseEvent(t, { bubbles: true, cancelable: true, view: window }))
      }
      n = n.parentElement
    }
  }

  // 只认「真正的按钮」，而且文字必须正好是朗读/停止朗读/停止播放。
  // 以前那版会匹配「类名里带 tts 的任何元素」，结果抓到的是 tts-engine 那种大容器，
  // 点上去当然没反应 —— 这就是「找不到朗读按钮 / 点了没用」的元凶。
  function looksLikeRead(el) {
    const tag = el.tagName ? el.tagName.toLowerCase() : ''
    const role = (el.getAttribute && el.getAttribute('role') ? el.getAttribute('role') : '').toLowerCase()
    if (tag !== 'button' && role !== 'button') return false
    const a = (el.getAttribute('aria-label') || '').trim()
    const t = (el.getAttribute('title') || '').trim()
    const txt = (el.innerText || '').trim()
    const dt = (el.getAttribute('data-testid') || '').toLowerCase()
    // ⚠ 2026-10-03：写上「朗读」但后面带了别的字（「朗读这条」「朗读回复」）也要认 ——
    //   原来只认**一字不差**的「朗读」，DeepSeek 稍微改一下文案就整条找不到了 ✗
    //   （「停止…」的按钮要排除，那是正在出声时的状态）
    const 像朗读 = (s) => !!s && s.indexOf('朗读') >= 0 && s.indexOf('停止') < 0
    return (
      a === '朗读' ||
      t === '朗读' ||
      txt === '朗读' ||
      像朗读(a) ||
      像朗读(t) ||
      a === '停止朗读' ||
      t === '停止朗读' ||
      a === '停止播放' ||
      t === '停止播放' ||
      dt.indexOf('tts') >= 0 ||
      /read aloud|read-aloud/i.test(a) ||
      /read aloud|read-aloud/i.test(t)
    )
  }

  function pickRead(root) {
    if (!root) return null
    const hits = Array.from(root.querySelectorAll('*')).filter(looksLikeRead)
    if (!hits.length) return null
    const vis = hits.filter(isVisible)
    return (vis.length ? vis : hits).pop()
  }

  // 最后那条的「朗读」按钮在不在？DeepSeek 对正在生成的消息不挂工具条，
  // 所以它一出现就说明这条定稿了 —— 而工具条出现本身就是一次页面变化，
  // 不用等被 Chrome 掐慢的定时器，后台也一样立刻能判出来。
  function readReadyNearLast() {
    const last = lastMarkdown()
    if (!last) return false
    let n = last
    for (let i = 0; i < 6 && n; i++) {
      const hit = pickRead(n)
      if (hit) {
        try {
          // 必须在最后这条「之后」—— 否则可能是上一条的按钮
          return !!(last.compareDocumentPosition(hit) & Node.DOCUMENT_POSITION_FOLLOWING)
        } catch (e) {
          return false
        }
      }
      n = n.parentElement
    }
    return false
  }

  // ⚠⚠⚠ 按钮必须属于**最后这一条** —— 判法跟 readReadyNearLast 一样：
  //   按钮在文档里的位置必须在 last **之后** ✓
  //   不这么判的后果（实测踩到的）：被拦时**最后这条没有朗读按钮**，
  //   它就一路往上找、最后全页面找 → 点到**上一条**的朗读，
  //   把**旧的内容**念出来 —— 比不弹提示还糟 ✗✗
  function 属于最后这条(hit, last) {
    if (!hit || !last) return false
    try {
      return !!(last.compareDocumentPosition(hit) & Node.DOCUMENT_POSITION_FOLLOWING)
    } catch (e) {
      return false
    }
  }

  // ⚠⚠⚠ 2026-10-03 改（反馈「内容发出去了，却报拦住、也不去点，得自己手点」）：
  //   原来这里**只找一轮**（直接找 → 划鼠标 400 毫秒 → 展开「更多」），前后大约一秒；
  //   找不到就报「被拦了」。可她撞到的正是这一条：**复述其实已经好了**（话也发出去了），
  //   只是工具条还没挂出来（长段落更慢）→ 报「被拦了」、也不去点；
  //   她过一会儿自己手点反而成 —— 因为那会儿按钮已经出来了 ✗✗
  //   → 现在改成**耐心找**：最多找约 15 秒，每一轮都滚到底、重新划一遍鼠标；
  //     真的一直没有，才说「没找到朗读按钮」——
  //     **不再把「按钮没出来」硬说成「被拦」（那是两码事，混着说她也没法分辨）** ✓
  async function findReadButton(check) {
    const 只看最后这条 = (last, root) => {
      const hit = pickRead(root || document)
      return 属于最后这条(hit, last) ? hit : null
    }
    // 先直接找 —— 等回复那一步多半已经确认「按钮挂出来了」，所以大多数情况这里一击即中，
    // 不用划鼠标、不用等那 0.4 秒
    const 快找 = (last) => {
      let n = last
      for (let i = 0; i < 6 && n; i++) {
        const hit = pickRead(n)
        if (属于最后这条(hit, last)) return hit
        n = n.parentElement
      }
      return 只看最后这条(last)
    }
    const t0 = Date.now()
    let 轮 = 0
    while (true) {
      check()
      轮++
      const last = lastMarkdown()
      const quick = 快找(last)
      if (quick) return quick
      // 没找到：滚到底 + 划鼠标让工具条浮出来，再找一遍
      if (last) {
        scrollToBottom()
        revealToolbar(last)
        await sleep(400)
        check()
        const second = 快找(last)
        if (second) return second
      }
      // 还没找到：试着点开「更多」再看一次（只在前两轮点，免得点开又点关上）
      if (last && 轮 <= 2) {
        let n = last
        for (let i = 0; i < 4 && n; i++) {
          const more = Array.from(n.querySelectorAll('button, [role="button"], [aria-label], [title]'))
            .filter((el) => isVisible(el) && /更多|more|⋯|\.\.\./.test(labels(el)))
            .pop()
          if (more) {
            check()
            more.click()
            await sleep(600)
            check()
            const hit = 只看最后这条(last)
            if (hit) return hit
          }
          n = n.parentElement
        }
      }
      if (Date.now() - t0 > 15000) throw fail('没找到朗读按钮')
      await sleep(400)
    }
  }

  // 播放中会变成「停止朗读」
  function playingMark() {
    for (const el of document.querySelectorAll('[aria-label], [title], button, [role="button"]')) {
      if (/停止朗读|停止播放/.test(attrs(el))) return true
    }
    return false
  }

  // ---------- 主流程 ----------
  // 盯页面变化来判断「复述完了没」——比定时器靠谱，窗口最小化/后台也不会被掐慢
  // ⚠⚠ 页面里「被拦」那句话出现了几次 —— 用**数量变化**判「新出现」✓
  //   为什么要数数量：页面上**以前**的对话里可能就有同样的话（她聊过一次），
  //   光判「有没有」会一直误报 → 只有**比发之前多出来**才算这次被拦 ✗
  function countRefusal(t) {
    const s = String(t || '')
    let n = 0
    for (const w of REFUSAL_WORDS) {
      let i = -1
      while ((i = s.indexOf(w, i + 1)) >= 0) n++
    }
    return n
  }
  // 被拦时 DeepSeek **不挂朗读按钮**，所以「等按钮」那条判据永远不成立 ——
  //   必须另外从**页面文字**上认它，不能只等 markdown 节点 ✓
  //   （认出来就返回这个记号；以前是个全局标记，旧条目迟到的判定会改到新条目头上 ✗）
  const 被拦记号 = '__被拦__'

  // isActive：这条还算不算数（被停止 / 看门狗复位 / 新的一条接替就不算了）——
  //   不算数就立刻收手，不再认页面上的新回复（那可能是下一条的）✓
  async function waitForReply(beforeText, beforeCount, beforeNode, timeoutMs, 拒绝, isActive) {
    const t0 = Date.now()
    let last = ''
    let lastChange = Date.now()
    let same = 0
    let appeared = false
    let done = null
    let kick = null
    const 我方词 = 拒绝 && typeof 拒绝.我方词 === 'number' ? 拒绝.我方词 : 0
    const 页基准 = 拒绝 && typeof 拒绝.页基准 === 'number' ? 拒绝.页基准 : null
    const evaluate = () => {
      if (done || !isActive()) return
      // ⚠⚠⚠ 先认「被拦」—— 这条要放在**最前面**，而且**不依赖 markdown 节点**：
      //   被拦时没有朗读按钮、主判据永远不成立，会一路等到超时（200 秒）✗
      //   它拒绝时，页面上会多出那句
      //   「你好，这个问题我暂时无法回答，让我们换个话题再聊聊吧。」
      // ⚠ 2026-10-03 把判据收紧成两条（原来只看整页数量，会被我们自己发过去的那段带偏）：
      //   ① 末尾这条**新复述**里的拒绝词，比我们发过去的原文**还多** → 它自己加了那句拒绝 ✓
      //      （原文对白里本来就有「换个话题」这种话，复述出来一模一样 → 差是 0，不算 ✗）
      //   ② 新回复还没挂出来时，整页多出来的拒绝词要**超过我们那段话本身能带来的**才算 ✓
      if (页基准 !== null) {
        const nodes0 = document.querySelectorAll(MD_SEL)
        const node0 = nodes0.length ? nodes0[nodes0.length - 1] : null
        const cur0 = node0 && node0 !== beforeNode ? (node0.innerText || '').trim() : ''
        const 它多出来的 = cur0 ? countRefusal(cur0) - 我方词 : 0
        const 整页多出来的 = countRefusal(document.body.innerText || '') - 页基准 - 我方词
        if (它多出来的 > 0 || (!cur0 && 整页多出来的 > 0)) {
          done = 被拦记号
          return
        }
      }
      const nodes = document.querySelectorAll(MD_SEL)
      const node = nodes.length ? nodes[nodes.length - 1] : null
      const cur = node ? (node.innerText || '').trim() : ''
      // 主判据：末尾换成了一条全新的 markdown，而且它的朗读按钮已经挂出来了
      //（流式生成中的消息没有工具条）—— 这一下本身就是页面变化，不用等定时器
      if (node && node !== beforeNode && cur && !isGenerating() && readReadyNearLast()) {
        last = cur
        done = cur
        return
      }
      const fresh = cur && (nodes.length > beforeCount || cur !== beforeText)
      if (!fresh) return
      appeared = true
      if (cur !== last) {
        last = cur
        lastChange = Date.now()
        same = 0
        return
      }
      same++
      const quiet = Date.now() - lastChange
      // 主要判据：文字没变 + DeepSeek 把「停止生成」收掉了 —— 那一下本身就是页面变化，
      // 所以后台标签页里也立刻能判出来，不用等被掐慢的定时器。
      if ((!isGenerating() && same >= 2) || quiet >= 2500) done = cur
    }
    const obs = new MutationObserver(() => {
      evaluate()
      if (kick) clearTimeout(kick)
      kick = setTimeout(evaluate, 1900)
    })
    try {
      obs.observe(document.body, { childList: true, subtree: true, characterData: true })
    } catch (e) {}
    let shownLen = -1
    try {
      while (!done && isActive() && Date.now() - t0 < (timeoutMs || 200000)) {
        evaluate()
        const secs = Math.round((Date.now() - t0) / 1000)
        const want = appeared
          ? '等 DeepSeek 复述…（已收到 ' + last.length + ' 字）'
          : '已发出，等 DeepSeek 回话…（' + secs + ' 秒）'
        if (want !== status) {
          status = want
          noteUntil = Date.now() + 20000
          paint()
        }
        await sleep(500)
      }
    } finally {
      if (kick) clearTimeout(kick)
      obs.disconnect()
    }
    return done || (appeared ? last : null)
  }

  function readWarning() {
    const txt = document.body.innerText || ''
    for (const w of ['朗读已达今日限额', '朗读失败', '当前语言暂不支持朗读', '该音色已下线', '获取音色列表失败']) {
      if (txt.indexOf(w) >= 0) return w
    }
    return null
  }

  // ⚠⚠ 复述被拦：有些内容 DeepSeek 不肯原样重复，它会改口说一句拒绝 ——
  //   原话是：「你好，这个问题我暂时无法回答，让我们换个话题再聊聊吧。」
  //   这时候它**根本没在复述**，念出来等于念了句拒绝给她听，
  //   而旧代码看不出来，照点朗读、状态还写「念完了」→ 她以为没事 ✗
  //   → 认出来，卡片上就写「没成：被拦了」✓
  //
  //   ⚠⚠ 只认**它自己那套话**，不许拿「无法」「不能」这种通用词去撞 ——
  //     正文里本来就可能出现（小说对白、旁白），撞了就误报 ✗
  //   ⚠⚠ 而且**还要看我们发过去的那段里有没有**：
  //     要是原文自己就写着「换个话题」，那复述里出现它是**对的**，不能算被拦
  //     → 所以「回复里有、发过去的里没有」才算 ✓
  const REFUSAL_WORDS = [
    '暂时无法回答',
    '换个话题',
    '换一个话题',
    '聊点别的',
    '我们聊别的',
    '这个话题我不能',
    '这个问题我不能',
  ]
  function looksLikeRefusal(t) {
    const s = String(t || '')
    for (const w of REFUSAL_WORDS) if (s.indexOf(w) >= 0) return w
    return null
  }

  // isActive：这条还算不算数。每个 await 回来、在动页面（发送 / 点朗读）或改共享状态之前都要再问一次 ——
  //   看门狗复位 / 按了停止之后，旧条目慢吞吞醒过来，不许去点**新条目**的按钮 ✗
  async function speak(text, isActive) {
    const check = () => {
      if (!isActive()) throw fail('已取消')
    }
    check()
    const input = findInput()
    if (!input) throw fail('没找到对话框', dump(document, 20).join(' ;; '))
    // 发送前先记住「现在末尾是哪一条」——新回复是一条全新的 markdown 节点，
    // 靠「节点换人了」来认，比靠字数/条数稳得多（秒回的回复会把条数基准冲掉）
    const before = lastMarkdown()
    const beforeText = before ? (before.innerText || '').trim() : ''
    const beforeCount = document.querySelectorAll(MD_SEL).length
    // ⚠⚠ 发之前先数一下页面上「拒绝词」有几个 ——
    //   发完比这个数多，才可能是这次被拦的 ✓（光判「有没有」会被以前的对话误报）
    // ⚠ 2026-10-03：我们自己发过去的那段**也会显示在页面上**（用户消息一条、复述再一条），
    //   所以要把「我方词数」一起交给判据，让它扣掉这一截（见 waitForReply 里那两条）✗
    const beforeRefusal = countRefusal(document.body.innerText || '')
    const payload = PREFIX + text
    const 我方词 = countRefusal(payload)

    input.focus()
    setNativeValue(input, payload)
    await sleep(250)
    check()

    key(input, 'keydown')
    key(input, 'keypress')
    key(input, 'keyup')
    await sleep(900)
    check()
    const clearedByEnter = readInput(input) !== payload
    if (!clearedByEnter) {
      const btn = findSendButton(input)
      if (btn) {
        btn.click()
        await sleep(900)
        check()
      }
    }
    const cleared = readInput(input) !== payload

    // 发出去之后、等界面稳一下，再记「之前是什么样」——
    // 不然发送过程本身带来的渲染会被当成「DeepSeek 回复好了」
    status = '等 DeepSeek 复述…'
    paint()
    // ⚠⚠⚠ 2026-10-12 修（反馈「点了网页一点反应都没有」）
    //   这里第 4 个参数是**超时**，原来传的是 `undefined` →
    //   函数内部就用了默认值 **200 秒** ✗（它自己的注释写着「会一路等到超时（200 秒）」）
    //   → 她看到的就是"干等三分多钟、什么都不发生"✓ 而我在 25 秒/40 秒就去读记录 ✗ 当然读不到 ✓
    //   改成 45 秒：到点就走到下面的 fail('没发出去', diagnostics…) ✓
    //   那一报会把页面现场带回来（输入框还剩什么、有没有 node、朗读按钮在不在 ……）✓
    const reply = await waitForReply(
      beforeText,
      beforeCount,
      before,
      45000,
      {
        页基准: beforeRefusal,
        我方词: 我方词,
      },
      isActive,
    )
    check()
    // ⚠⚠⚠ 被拦了 —— 这条要**放在「没发出去」前面**判：
    //   被拦时没有朗读按钮、可能连 markdown 节点都没有 → reply 会是 null，
    //   走下面那条就会误报成「没发出去」，她看到的提示就是错的 ✗
    if (reply === 被拦记号) throw fail('被拦了')
    if (!reply) {
      throw fail(
        '没发出去',
        '清空=' + clearedByEnter + '/' + cleared + ' | 输入框还剩=' + readInput(input).slice(0, 30) + ' | ' + diagnostics(before),
      )
    }

    status = '点朗读…'
    paint()
    // ⚠⚠ 先看看它是不是在拒绝，再点朗读 ✗
    //   复述被拦时它回的是「…暂时无法回答，让我们换个话题再聊聊吧」——
    //   那不是复述，念出来是念了句拒绝给她听，不如**别念、直接告诉她** ✓
    //   ⚠ 判断两头看：**回复里有、发过去的原文里没有** 才算被拦 ——
    //     原文自己就写着「换个话题」（小说对白）的话，复述里出现是对的 ✗
    const 拦的词 = looksLikeRefusal(reply)
    if (拦的词 && !looksLikeRefusal(text)) {
      // ⚠ 话要短 —— 她说的：「太长了，就说被拦了就行」✗
      //   卡片上显示成「没成：被拦了」，一行看完 ✓
      throw fail('被拦了')
    }
    scrollToBottom()
    const btn = await findReadButton(check)
    check()
    btn.click()
    await sleep(800)
    check()
    // 页面上出现「限额」这类提示只当备注，不当结论 ——
    // 它可能是之前留下的、也可能弹一下又好了。真正的结论看有没有出声。
    lastWarning = readWarning()
    return lastWarning ? '页面提示：' + lastWarning : null
  }

  // 浏览器给的「这个标签页在出声吗」——比看图标准多了
  async function askAudible() {
    const r = await tell({ type: 'audible' })
    return !!(r && r.ok && r.data && r.data.audible)
  }

  function findReadOrStop() {
    const hits = Array.from(document.querySelectorAll('[aria-label], [title], button, [role="button"]')).filter((el) =>
      /^(朗读|停止朗读|停止播放)$/.test(((el.getAttribute('aria-label') || el.getAttribute('title') || '') + '').trim()),
    )
    const vis = hits.filter(isVisible)
    return (vis.length ? vis : hits).pop() || null
  }

  // 盯播放：第一次点经常只转图标不出声（DeepSeek 那边的解码资源还没热），
  // 所以静着就自动「停一下再点一次」——就是她手动发现的那个办法。
  // 成败以「浏览器说这个标签页到底有没有出声」为准，不看页面上出现了什么字。
  // ⚠ 一出声**不算完**：要等它真念完（连续静 3 次）才回执，否则下一条会把这一条打断 ✗
  //   具体规则在 playback.js（能拿假时钟测）；这里只接上页面这头的手脚。
  // base / isActive 都是这一条进门时定下的：旧条目的 playing 不许写到另一个窝，也不许动新条目的状态
  // ⭐ 按这一条的字数估一个上限：正常朗读大约 3~4 字/秒，再给 30 秒余量。
