  const DS_POS_KEY = 'xb-tts-ds-panel-pos'
  function applyDsPos(p) {
    panel.style.left = Math.round(p.x) + 'px'
    panel.style.top = Math.round(p.y) + 'px'
    panel.style.right = 'auto'
    panel.style.bottom = 'auto'
